import { cpSync } from 'node:fs';
import { defineConfig } from 'tsup';

// Two self-contained entry points: the server, and the migration runner used by the initContainer.
// SQL migrations generated by drizzle-kit are copied next to them.
export default defineConfig({
  entry: { server: 'src/main.ts', migrate: 'src/db/migrate-main.ts' },
  format: ['esm'],
  platform: 'node',
  target: 'node24',
  noExternal: [/.*/],
  splitting: false,
  sourcemap: true,
  clean: true,
  outExtension: () => ({ js: '.mjs' }),
  // Bundled CommonJS dependencies still call require(); give the ESM bundle a real one.
  banner: {
    js: "import { createRequire as __createRequire } from 'node:module'; const require = __createRequire(import.meta.url);",
  },
  onSuccess: async () => {
    cpSync('drizzle', 'dist/migrations', { recursive: true });
  },
});
